{
  "name": "aincrad-online",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Aincrad Online — a SAO-inspired open-world 3D action RPG for mobile and desktop.",
  "scripts": {
    "dev": "vite",
    "build": "vite build --base ./",
    "preview": "vite preview"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "^7.3.7"
  }
}

import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  server: { host: true, port: 3002, strictPort: true },
  build: { target: 'es2020', assetsInlineLimit: 0 }
})

/* Aincrad Online — UI system */
:root{
  --ink:#eaf7ff;
  --muted:#9fb6c9;
  --cyan:#7fe7ff;
  --cyan-strong:#39d7ff;
  --violet:#a48bff;
  --gold:#ffcf7a;
  --danger:#ff5d6c;
  --hp:#54e6a8;
  --panel:rgba(8,18,30,.62);
  --panel-strong:rgba(7,15,26,.86);
  --line:rgba(127,231,255,.28);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-t:env(safe-area-inset-top,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#071019;color:var(--ink);
  font-family:"Trebuchet MS","Segoe UI",system-ui,-apple-system,sans-serif;
  -webkit-user-select:none;user-select:none;overscroll-behavior:none}
#app{position:fixed;inset:0;overflow:hidden}
#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;outline:none}
.hidden{display:none !important}
button{font-family:inherit;color:inherit;border:none;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}

/* ══════════ HUD ══════════ */
#hud{position:absolute;inset:0;pointer-events:none;z-index:5}
.panel{background:linear-gradient(150deg,rgba(10,24,40,.82),rgba(6,14,25,.66));
  border:1px solid var(--line);border-radius:10px;
  box-shadow:0 10px 30px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
#topbar{position:absolute;top:calc(10px + var(--safe-t));left:calc(12px + var(--safe-l));right:calc(12px + var(--safe-r));
  display:flex;align-items:flex-start;gap:12px;justify-content:space-between}
#player-panel{display:flex;gap:10px;padding:8px 12px 8px 8px;width:min(46vw,430px);min-width:270px}
.avatar{position:relative;width:44px;height:44px;flex:none;border-radius:8px;color:var(--cyan);
  background:radial-gradient(circle at 35% 25%,rgba(127,231,255,.22),rgba(7,18,30,.9));
  border:1px solid rgba(127,231,255,.4);display:grid;place-items:center}
.avatar svg{width:30px;height:30px}
.avatar span{position:absolute;right:-6px;bottom:-6px;background:#0a1725;border:1px solid var(--cyan);
  color:var(--cyan);font-size:11px;font-weight:800;width:21px;height:21px;border-radius:50%;display:grid;place-items:center}
.bars{flex:1;min-width:0}
.name-row{display:flex;justify-content:space-between;align-items:baseline;font-size:11px;letter-spacing:.16em;margin-bottom:4px}
#player-name{font-weight:800;color:#f2fbff;font-size:13px}
.col{color:var(--gold);letter-spacing:.05em;font-size:12px;font-weight:700}
.hp-track{position:relative;height:15px;border-radius:4px;background:rgba(0,0,0,.55);overflow:hidden;
  border:1px solid rgba(255,255,255,.12);box-shadow:inset 0 2px 6px rgba(0,0,0,.6)}
.hp-track.small{height:10px}
.hp-fill{height:100%;width:100%;background:linear-gradient(90deg,#2ecf8d,#73f5bb 55%,#b6ffdc);
  border-radius:3px;transition:width .18s ease-out;box-shadow:0 0 12px rgba(84,230,168,.55)}
.hp-fill.enemy{background:linear-gradient(90deg,#ff5c69,#ff9c6e)}
.hp-fill.boss{background:linear-gradient(90deg,#ff4a63,#ff9d4d);box-shadow:0 0 16px rgba(255,93,108,.6)}
.hp-track>span{position:absolute;inset:0;display:grid;place-items:center;font-size:10px;font-weight:800;
  color:#effff9;text-shadow:0 1px 3px #000;letter-spacing:.08em}
.xp-track{height:3px;background:rgba(255,255,255,.1);border-radius:2px;margin-top:4px;overflow:hidden}
#player-xp-fill{height:100%;width:0%;background:linear-gradient(90deg,var(--violet),var(--cyan));transition:width .3s}

#target-panel{position:absolute;left:50%;transform:translateX(-50%);width:min(40vw,330px);padding:7px 12px 9px;margin-top:2px}
.target-head{display:flex;justify-content:space-between;font-size:11px;letter-spacing:.12em;margin-bottom:5px}
#target-name{font-weight:800;color:#ffd6d9}
#target-lvl{color:var(--muted)}

#topright{display:flex;gap:8px;align-items:flex-start}
#minimap-wrap{position:relative;width:132px;height:132px;padding:6px;border-radius:50%}
#minimap{width:100%;height:100%;border-radius:50%;display:block;background:rgba(3,12,20,.7)}
.compass{position:absolute;top:-2px;left:50%;transform:translateX(-50%);font-size:9px;color:var(--cyan);letter-spacing:.2em;
  background:#0a1725;padding:0 5px;border-radius:6px;border:1px solid var(--line)}
#minimap-zone{position:absolute;bottom:-16px;left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:.18em;
  color:var(--muted);white-space:nowrap;text-transform:uppercase}
.icon-btn{pointer-events:auto;width:38px;height:38px;border-radius:9px;border:1px solid var(--line);
  background:var(--panel);color:var(--cyan);display:grid;place-items:center;backdrop-filter:blur(6px)}
.icon-btn svg{width:21px;height:21px}

#quest-tracker{position:absolute;top:calc(160px + var(--safe-t));right:calc(14px + var(--safe-r));
  width:min(30vw,250px);padding:10px 12px;border-left:2px solid var(--cyan)}
.quest-kicker{font-size:8px;letter-spacing:.3em;color:var(--cyan);opacity:.9;margin-bottom:4px}
#quest-title{font-size:13px;font-weight:800;letter-spacing:.04em;margin-bottom:3px}
#quest-objective{font-size:11px;color:var(--muted);line-height:1.35}
#quest-count{font-size:11px;color:var(--gold);margin-top:4px;font-weight:700;letter-spacing:.1em}

#boss-bar{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(96px + var(--safe-b));width:min(62vw,600px)}
.boss-name{text-align:center;font-size:11px;letter-spacing:.3em;color:#ffd9a1;text-shadow:0 2px 8px #000;margin-bottom:5px;font-weight:800}
.hp-track.boss{height:14px;border-color:rgba(255,180,120,.4)}
.boss-phase{text-align:center;font-size:8px;letter-spacing:.3em;color:var(--muted);margin-top:4px}

#interact-prompt{position:absolute;left:50%;top:62%;transform:translateX(-50%);pointer-events:auto;
  display:flex;align-items:center;gap:8px;padding:8px 14px;border-radius:30px;background:rgba(7,16,28,.86);
  border:1px solid var(--line);font-size:11px;letter-spacing:.16em;font-weight:800;color:var(--ink);
  box-shadow:0 6px 24px rgba(0,0,0,.45);animation:pulsePrompt 1.8s ease-in-out infinite}
.key{display:grid;place-items:center;width:22px;height:22px;border-radius:5px;border:1px solid var(--cyan);
  color:var(--cyan);font-size:11px;background:rgba(127,231,255,.1)}
@keyframes pulsePrompt{0%,100%{transform:translateX(-50%) scale(1)}50%{transform:translateX(-50%) scale(1.04)}}

#toasts{position:absolute;left:50%;top:24%;transform:translateX(-50%);display:flex;flex-direction:column;gap:6px;align-items:center;width:90%}
.toast{padding:7px 16px;border-radius:6px;background:rgba(6,15,26,.88);border:1px solid var(--line);
  font-size:11px;letter-spacing:.14em;font-weight:800;color:var(--cyan);animation:toastIn .25s ease-out,toastOut .4s ease-in 2.4s forwards;
  box-shadow:0 6px 18px rgba(0,0,0,.4);text-align:center;max-width:100%}
.toast.gold{color:var(--gold);border-color:rgba(255,207,122,.4)}
.toast.danger{color:#ff9aa3;border-color:rgba(255,93,108,.4)}
.toast.big{font-size:14px;padding:10px 22px;letter-spacing:.2em}
@keyframes toastIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-10px)}}

#vignette{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .18s;
  background:radial-gradient(ellipse at center,transparent 42%,rgba(255,20,40,.55) 100%)}
#vignette.hit{opacity:1}
#vignette.low{opacity:.6;background:radial-gradient(ellipse at center,transparent 55%,rgba(140,0,15,.55) 100%)}

/* ══════════ CONTROLS ══════════ */
#controls{position:absolute;inset:0;pointer-events:none}
#stick-zone{position:absolute;left:calc(20px + var(--safe-l));bottom:calc(18px + var(--safe-b));
  width:150px;height:150px;pointer-events:auto;touch-action:none}
#stick-base{position:absolute;left:12px;top:2px;width:112px;height:112px;border-radius:50%;
  background:radial-gradient(circle,rgba(14,32,50,.55),rgba(7,16,28,.28));
  border:1.5px solid rgba(127,231,255,.3);box-shadow:inset 0 0 26px rgba(0,0,0,.5),0 0 18px rgba(0,0,0,.25)}
.stick-ring{position:absolute;inset:17px;border-radius:50%;border:1px dashed rgba(127,231,255,.18)}
#stick-knob{position:absolute;left:50%;top:50%;width:52px;height:52px;border-radius:50%;transform:translate(-50%,-50%);
  background:radial-gradient(circle at 38% 32%,rgba(190,246,255,.95),rgba(60,190,230,.55) 45%,rgba(10,45,70,.7));
  border:1.5px solid rgba(200,250,255,.7);box-shadow:0 4px 18px rgba(0,0,0,.45),0 0 14px rgba(80,220,255,.35);
  transition:transform .06s linear}
.stick-hint{position:absolute;left:0;right:0;bottom:-13px;text-align:center;font-size:8px;letter-spacing:.28em;color:rgba(160,200,225,.6)}

#action-cluster{position:absolute;right:calc(16px + var(--safe-r));bottom:calc(16px + var(--safe-b));
  width:264px;height:210px;pointer-events:none}
.act{position:absolute;pointer-events:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;
  border-radius:50%;color:#eafcff;background:radial-gradient(circle at 35% 28%,rgba(30,76,104,.92),rgba(7,20,34,.94));
  border:1.5px solid rgba(127,231,255,.4);box-shadow:0 4px 18px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.15);
  transition:transform .08s,filter .1s;touch-action:none}
.act:active,.act.pressed{transform:scale(.93);filter:brightness(1.3)}
.act svg{width:22px;height:22px;flex:none}
.act .lbl{font-size:7px;letter-spacing:.14em;font-weight:800;margin-top:2px;opacity:.9}
.act .cd{position:absolute;inset:0;border-radius:50%;display:none;place-items:center;background:rgba(2,8,14,.72);
  font-size:15px;font-weight:800;color:#dff8ff;letter-spacing:.02em}
.act.cooling .cd{display:grid}
.attack{right:8px;bottom:0;width:104px;height:104px;border-color:rgba(255,190,120,.55);
  background:radial-gradient(circle at 35% 28%,rgba(104,54,25,.95),rgba(30,15,10,.95));color:#ffe1b0}
.attack svg{width:40px;height:40px}
.attack .lbl{font-size:9px;letter-spacing:.18em;color:#ffd9a1}
.skill{right:86px;bottom:98px;width:72px;height:72px;border-color:rgba(180,150,255,.6);
  background:radial-gradient(circle at 35% 28%,rgba(75,48,130,.95),rgba(16,12,36,.95));color:#d9ccff}
.skill svg{width:26px;height:26px}
.skill .lbl{font-size:7px;color:#cbb9ff}
.jump{right:188px;bottom:132px;width:50px;height:50px;color:#c8f1ff}
.dodge{right:158px;bottom:64px;width:50px;height:50px;color:#a8e9ff}
.lock{right:18px;bottom:118px;width:46px;height:46px;color:#ffd0a2;border-color:rgba(255,200,140,.4)}
.potion{right:250px;bottom:12px;width:46px;height:46px;color:#a9ffcc;border-color:rgba(120,255,180,.4)}
.potion .count{position:absolute;top:-4px;right:-4px;background:#0b1c2a;border:1px solid rgba(120,255,180,.6);
  color:#a9ffcc;border-radius:8px;font-size:9px;font-weight:800;min-width:17px;height:17px;display:grid;place-items:center;padding:0 3px}
.interact-btn{right:250px;bottom:142px;width:58px;height:58px;color:#ffe3a8;border-color:rgba(255,220,140,.6);
  animation:interactPop 1.6s ease-in-out infinite}
.interact-btn .lbl{font-size:7px;letter-spacing:.06em}
@keyframes interactPop{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}

.hint{position:absolute;left:50%;bottom:calc(22px + var(--safe-b));transform:translateX(-50%);
  font-size:10px;letter-spacing:.16em;color:rgba(200,225,240,.72);background:rgba(5,12,20,.55);
  padding:6px 14px;border-radius:20px;white-space:nowrap;transition:opacity .6s;pointer-events:none}

/* ══════════ TITLE ══════════ */
#title-screen{position:absolute;inset:0;z-index:20;display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:radial-gradient(ellipse at 50% 38%,rgba(4,14,26,.18) 0%,rgba(3,10,19,.55) 48%,rgba(2,7,14,.94) 100%);
  text-align:center;padding:24px}
.title-vignette{position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(180deg,rgba(2,8,15,.45),transparent 30%,transparent 62%,rgba(2,7,14,.9))}
.title-inner{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;max-width:820px;width:100%}
.crest{width:82px;height:96px;color:var(--cyan);filter:drop-shadow(0 0 16px rgba(80,220,255,.55));margin-bottom:6px;
  animation:crestFloat 5s ease-in-out infinite}
@keyframes crestFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
.title-kicker{font-size:9px;letter-spacing:.5em;color:rgba(180,230,250,.75);margin-bottom:10px}
.logo{margin:0;font-size:clamp(52px,10vw,104px);line-height:.86;letter-spacing:.055em;font-weight:900;
  color:#f2fbff;text-shadow:0 0 34px rgba(90,215,255,.28),0 4px 0 rgba(0,0,0,.35)}
.logo span{display:block;font-size:clamp(21px,3.2vw,32px);letter-spacing:.72em;color:var(--cyan);
  font-weight:700;margin-top:8px;text-shadow:0 0 22px rgba(80,220,255,.55);padding-left:.72em}
.tagline{font-size:clamp(11px,1.5vw,14px);letter-spacing:.14em;color:var(--muted);margin:18px 0 24px}
.title-actions{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.primary-btn{padding:14px 34px;border-radius:7px;font-size:12px;font-weight:900;letter-spacing:.22em;color:#04121a;
  background:linear-gradient(135deg,#b8f5ff,#42d4ff 55%,#1f9fd6);border:1px solid rgba(210,250,255,.9);
  box-shadow:0 0 26px rgba(60,210,255,.35),0 8px 20px rgba(0,0,0,.4);transition:transform .12s,filter .15s}
.primary-btn:hover{filter:brightness(1.1);transform:translateY(-1px)}
.primary-btn:active{transform:translateY(1px) scale(.99)}
.ghost-btn{padding:13px 26px;border-radius:7px;font-size:11px;font-weight:800;letter-spacing:.18em;color:#d8f2ff;
  background:rgba(10,26,42,.55);border:1px solid rgba(127,231,255,.4);transition:background .15s}
.ghost-btn:hover{background:rgba(20,48,72,.7)}
.title-meta{display:flex;gap:12px;align-items:center;font-size:8px;letter-spacing:.3em;color:rgba(170,205,225,.7);margin-top:26px}
.title-meta .dot{width:3px;height:3px;border-radius:50%;background:var(--cyan);opacity:.7}
.title-controls{display:flex;gap:22px;margin-top:16px;font-size:9px;letter-spacing:.08em;color:rgba(170,205,225,.65);flex-wrap:wrap;justify-content:center}
.title-controls b{color:rgba(200,240,255,.95);letter-spacing:.1em}
.title-footer{position:absolute;bottom:calc(12px + var(--safe-b));left:0;right:0;z-index:3;display:flex;justify-content:center;gap:18px;
  font-size:8px;letter-spacing:.18em;color:rgba(150,185,205,.55);padding:0 16px;flex-wrap:wrap;align-items:center}
.sound-toggle{font-size:8px;letter-spacing:.18em;color:rgba(160,210,235,.7);border:1px solid rgba(127,231,255,.22);
  padding:4px 9px;border-radius:4px;background:rgba(5,13,22,.6)}
body.started #title-screen{display:none}

/* ══════════ DIALOG ══════════ */
#dialog{position:absolute;inset:0;z-index:15;display:flex;align-items:flex-end;justify-content:center;
  background:linear-gradient(0deg,rgba(2,7,14,.85),transparent 60%);padding:0 16px calc(24px + var(--safe-b))}
.dialog-card{width:min(680px,94vw);display:flex;gap:14px;padding:16px;border-radius:12px;
  background:linear-gradient(150deg,rgba(12,28,45,.97),rgba(6,14,25,.97));border:1px solid var(--line);
  box-shadow:0 18px 50px rgba(0,0,0,.6);animation:dialogIn .22s ease-out}
@keyframes dialogIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
.dialog-portrait{width:64px;height:64px;flex:none;border-radius:9px;border:1px solid rgba(127,231,255,.35);
  background:radial-gradient(circle at 40% 30%,#33526b,#0b1a29);display:grid;place-items:center;font-size:22px;font-weight:900;color:var(--cyan)}
.dialog-body{flex:1;min-width:0}
.dialog-name{font-size:10px;letter-spacing:.3em;color:var(--cyan);font-weight:800;margin-bottom:6px}
#dialog-text{font-size:13px;line-height:1.55;color:#dbeef9;margin:0 0 12px}
.dialog-actions{display:flex;gap:8px;flex-wrap:wrap}
.dialog-actions button{padding:9px 18px;border-radius:5px;font-size:10px;letter-spacing:.14em;font-weight:800;
  background:rgba(30,80,110,.6);border:1px solid rgba(127,231,255,.4);color:#e6faff}
.dialog-actions button.accent{background:linear-gradient(135deg,#9beeff,#2ec6f5);color:#04121a;border-color:#c8f6ff}
.dialog-actions button.close{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.16);color:var(--muted)}

/* ══════════ MENUS ══════════ */
#pause,#death,#victory,#fatal{position:absolute;inset:0;z-index:25;display:grid;place-items:center;padding:20px;
  background:rgba(2,8,15,.72);backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}
.menu-card,.death-card,.victory-card{width:min(420px,92vw);padding:26px;border-radius:14px;text-align:center;
  background:linear-gradient(160deg,rgba(12,28,46,.98),rgba(5,12,22,.98));border:1px solid var(--line);
  box-shadow:0 24px 70px rgba(0,0,0,.65);animation:dialogIn .25s ease-out}
.menu-kicker,.death-kicker{font-size:8px;letter-spacing:.4em;color:var(--cyan);margin-bottom:6px}
.menu-card h2,.death-card h2,.victory-card h2{margin:0 0 6px;font-size:28px;letter-spacing:.14em;font-weight:900}
