import * as THREE from 'three'

/* ── math ─────────────────────────────────────────── */
export const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const TAU = Math.PI * 2

export function smoothstep(e0, e1, x) {
  const t = clamp((x - e0) / (e1 - e0), 0, 1)
  return t * t * (3 - 2 * t)
}
export function angleDiff(a, b) {
  let d = (b - a) % TAU
  if (d > Math.PI) d -= TAU
  if (d < -Math.PI) d += TAU
  return d
}
export const angleLerp = (a, b, t) => a + angleDiff(a, b) * t

export function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/* deterministic 2D value noise, used by terrain prop scatter */
export function hash2(x, y) {
  let h = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123
  return h - Math.floor(h)
}
export function noise2(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y)
  const xf = x - xi, yf = y - yi
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf)
  const a = hash2(xi, yi), b = hash2(xi + 1, yi)
  const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1)
  return lerp(lerp(a, b, u), lerp(c, d, u), v)
}
export function fbm(x, y, oct = 4) {
  let v = 0, amp = 0.5, f = 1
  for (let i = 0; i < oct; i++) { v += amp * noise2(x * f, y * f); f *= 2.03; amp *= 0.5 }
  return v
}

/* ── canvas textures ──────────────────────────────── */
const texCache = new Map()

export function radialGlow(color = '#9feaff', inner = 0.05, mid = 0.45) {
  const key = `glow:${color}:${inner}:${mid}`
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas'); c.width = c.height = 128
  const g = c.getContext('2d')
  const grad = g.createRadialGradient(64, 64, 2, 64, 64, 64)
  grad.addColorStop(0, color)
  grad.addColorStop(inner, color)
  grad.addColorStop(mid, color.replace(')', ',0.35)').replace('rgb', 'rgba'))
  grad.addColorStop(1, 'rgba(0,0,0,0)')
  g.fillStyle = grad; g.fillRect(0, 0, 128, 128)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, t)
  return t
}

export function glowTexture() {
  const key = 'glowtex'
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas'); c.width = c.height = 64
  const g = c.getContext('2d')
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32)
  grad.addColorStop(0, 'rgba(255,255,255,1)')
  grad.addColorStop(0.25, 'rgba(190,240,255,0.85)')
  grad.addColorStop(0.6, 'rgba(120,210,255,0.28)')
  grad.addColorStop(1, 'rgba(80,150,255,0)')
  g.fillStyle = grad; g.fillRect(0, 0, 64, 64)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, t)
  return t
}

export function slashTexture() {
  const key = 'slash'
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas'); c.width = 256; c.height = 64
  const g = c.getContext('2d')
  g.clearRect(0, 0, 256, 64)
  const grad = g.createLinearGradient(0, 0, 256, 0)
  grad.addColorStop(0, 'rgba(120,230,255,0)')
  grad.addColorStop(0.22, 'rgba(160,245,255,0.65)')
  grad.addColorStop(0.55, 'rgba(255,255,255,1)')
  grad.addColorStop(0.8, 'rgba(130,220,255,0.55)')
  grad.addColorStop(1, 'rgba(80,180,255,0)')
  g.fillStyle = grad; g.fillRect(0, 0, 256, 64)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, t)
  return t
}

export function petalTexture() {
  const key = 'petal'
  if (texCache.has(key)) return texCache.get(key)
  const c = document.createElement('canvas'); c.width = c.height = 32
  const g = c.getContext('2d')
  g.translate(16, 16); g.rotate(0.6)
  const grad = g.createRadialGradient(0, 0, 0, 0, 0, 13)
  grad.addColorStop(0, 'rgba(255,240,248,1)')
  grad.addColorStop(0.55, 'rgba(255,190,220,0.95)')
  grad.addColorStop(1, 'rgba(255,150,200,0)')
  g.fillStyle = grad
  g.beginPath(); g.ellipse(0, 0, 6, 12, 0, 0, TAU); g.fill()
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  texCache.set(key, t)
  return t
}

/* A label sprite. Uses a canvas with crisp text. */
export function labelSprite(text, { color = '#dff8ff', bg = 'rgba(5,14,24,.72)', border = 'rgba(127,231,255,.4)', size = 42, scale = 1 } = {}) {
  const c = document.createElement('canvas')
  const padX = 18, padY = 10
  const g = c.getContext('2d')
  g.font = `700 ${size}px "Trebuchet MS", sans-serif`
  const w = Math.ceil(g.measureText(text).width) + padX * 2
  const h = size + padY * 2
  c.width = w; c.height = h
  const ctx = c.getContext('2d')
  ctx.fillStyle = bg
  roundRect(ctx, 1, 1, w - 2, h - 2, 12); ctx.fill()
  ctx.strokeStyle = border; ctx.lineWidth = 2
  roundRect(ctx, 1, 1, w - 2, h - 2, 12); ctx.stroke()
  ctx.fillStyle = color
  ctx.font = `700 ${size}px "Trebuchet MS", sans-serif`
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
  ctx.fillText(text, w / 2, h / 2 + 1)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  const mat = new THREE.SpriteMaterial({ map: t, transparent: true, depthWrite: false, depthTest: true })
  const s = new THREE.Sprite(mat)
  s.scale.set((w / h) * 0.55 * scale, 0.55 * scale, 1)
  return s
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2)
  ctx.beginPath()
  ctx.moveTo(x + rr, y)
  ctx.arcTo(x + w, y, x + w, y + h, rr)
  ctx.arcTo(x + w, y + h, x, y + h, rr)
  ctx.arcTo(x, y + h, x, y, rr)
  ctx.arcTo(x, y, x + w, y, rr)
  ctx.closePath()
}

/* damage number sprite texture cache */
const numberCache = new Map()
export function numberTexture(text, color = '#ffe27a', fontSize = 64) {
  const key = `${text}|${color}|${fontSize}`
  if (numberCache.has(key)) return numberCache.get(key)
  const c = document.createElement('canvas'); c.width = 256; c.height = 128
  const g = c.getContext('2d')
  g.font = `900 ${fontSize}px "Trebuchet MS", sans-serif`
  g.textAlign = 'center'; g.textBaseline = 'middle'
  g.lineWidth = 9; g.strokeStyle = 'rgba(0,10,20,.85)'
  g.strokeText(text, 128, 66)
  g.fillStyle = color
  g.fillText(text, 128, 66)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  numberCache.set(key, t)
  return t
}

/* random point helpers */
export function shuffle(arr, rng = Math.random) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    ;[arr[i], arr[j]] = [arr[j], arr[i]]
  }
  return arr
}

export function disposeObject(obj) {
  obj.traverse(o => {
    if (o.geometry) o.geometry.dispose()
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material]
      for (const m of mats) {
        if (m.map && m.map.__owned) m.map.dispose()
        m.dispose()
      }
    }
  })
}

/* Procedural audio — no external assets, tiny footprint. */
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.muted = false
    this.started = false
    this._wind = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    const ctx = new AC()
    this.ctx = ctx
    const master = ctx.createGain()
    master.gain.value = this.muted ? 0 : 0.55
    master.connect(ctx.destination)
    this.master = master
    this._startAmbient()
  }

  setMuted(m) {
    this.muted = m
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime)
      this.master.gain.linearRampToValueAtTime(m ? 0 : 0.55, this.ctx.currentTime + 0.2)
    }
  }

  _now() { return this.ctx ? this.ctx.currentTime : 0 }

  _noiseBuffer(dur = 0.3) {
    const ctx = this.ctx
    const len = Math.max(1, Math.floor(ctx.sampleRate * dur))
    const buf = ctx.createBuffer(1, len, ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1
    return buf
  }

  _noise(dur, { type = 'bandpass', f0 = 1000, f1 = null, q = 1.2, gain = 0.25, attack = 0.005 } = {}) {
    if (!this.ctx) return
    const ctx = this.ctx, t = ctx.currentTime
    const src = ctx.createBufferSource(); src.buffer = this._noiseBuffer(dur)
    const filt = ctx.createBiquadFilter(); filt.type = type; filt.Q.value = q
    filt.frequency.setValueAtTime(f0, t)
    if (f1) filt.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(filt).connect(g).connect(this.master)
    src.start(t); src.stop(t + dur + 0.02)
  }

  _tone(freq, dur, { type = 'sine', gain = 0.2, f1 = null, delay = 0, attack = 0.006, dest = null } = {}) {
    if (!this.ctx) return
    const ctx = this.ctx, t = ctx.currentTime + delay
    const o = ctx.createOscillator(); o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (f1) o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g).connect(dest || this.master)
    o.start(t); o.stop(t + dur + 0.03)
  }

  _startAmbient() {
    const ctx = this.ctx
    const bus = ctx.createGain()
    bus.gain.value = 0
    bus.connect(this.master)
    bus.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 4)
    this.ambientBus = bus

    // warm A-major pad
    const chord = [110, 164.81, 220, 329.63]
    for (const f of chord) {
      const o = ctx.createOscillator()
      o.type = f > 200 ? 'sine' : 'triangle'
      o.frequency.value = f
      o.detune.value = (Math.random() - 0.5) * 8
      const g = ctx.createGain(); g.gain.value = 0.018
      const lfo = ctx.createOscillator(); lfo.frequency.value = 0.05 + Math.random() * 0.08
      const lg = ctx.createGain(); lg.gain.value = 0.012
      lfo.connect(lg).connect(g.gain)
      const filt = ctx.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 900
      o.connect(filt).connect(g).connect(bus)
      o.start(); lfo.start()
    }
    // wind
    const wind = ctx.createBufferSource()
    wind.buffer = this._noiseBuffer(4)
    wind.loop = true
    const wf = ctx.createBiquadFilter(); wf.type = 'lowpass'; wf.frequency.value = 420; wf.Q.value = 0.6
    const wg = ctx.createGain(); wg.gain.value = 0.05
    const wlfo = ctx.createOscillator(); wlfo.frequency.value = 0.09
    const wlg = ctx.createGain(); wlg.gain.value = 0.025
    wlfo.connect(wlg).connect(wg.gain)
    wind.connect(wf).connect(wg).connect(bus)
    wind.start(); wlfo.start()
    this._wind = wind
  }

  slash() {
    this._noise(0.18, { type: 'bandpass', f0: 2600, f1: 340, q: 1.6, gain: 0.22 })
    this._tone(420, 0.1, { type: 'sawtooth', gain: 0.03, f1: 160 })
  }
  heavy() {
    this._noise(0.3, { type: 'lowpass', f0: 900, f1: 120, q: 0.8, gain: 0.34 })
    this._tone(90, 0.28, { type: 'sine', gain: 0.22, f1: 40 })
  }
  hit() {
    this._noise(0.12, { type: 'lowpass', f0: 1400, f1: 200, gain: 0.28 })
    this._tone(150, 0.12, { type: 'triangle', gain: 0.16, f1: 60 })
  }
  crit() {
    this._tone(1180, 0.14, { type: 'sine', gain: 0.15, f1: 1800 })
    this._noise(0.16, { type: 'highpass', f0: 2500, gain: 0.18 })
  }
  coin() {
    this._tone(1046, 0.12, { type: 'sine', gain: 0.08 })
    this._tone(1568, 0.22, { type: 'sine', gain: 0.06, delay: 0.07 })
  }
  heal() {
    this._tone(523, 0.22, { type: 'sine', gain: 0.09 })
    this._tone(784, 0.3, { type: 'sine', gain: 0.07, delay: 0.09 })
    this._tone(1046, 0.4, { type: 'sine', gain: 0.05, delay: 0.18 })
  }
  levelUp() {
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5]
    notes.forEach((f, i) => this._tone(f, 0.5, { type: 'triangle', gain: 0.09, delay: i * 0.09 }))
  }
  hurt() {
    this._noise(0.22, { type: 'lowpass', f0: 700, f1: 90, gain: 0.3 })
    this._tone(110, 0.3, { type: 'sawtooth', gain: 0.1, f1: 55 })
  }
  dash() {
    this._noise(0.26, { type: 'bandpass', f0: 500, f1: 2200, q: 1.4, gain: 0.14 })
  }
  jump() {
    this._tone(320, 0.16, { type: 'sine', gain: 0.06, f1: 620 })
  }
  interact() {
    this._tone(880, 0.09, { type: 'sine', gain: 0.06 })
    this._tone(1320, 0.14, { type: 'sine', gain: 0.04, delay: 0.06 })
  }
  ui() {
    this._tone(740, 0.06, { type: 'sine', gain: 0.045 })
  }
  deny() {
    this._tone(180, 0.12, { type: 'square', gain: 0.05, f1: 120 })
  }
  death() {
    this._tone(220, 0.8, { type: 'sawtooth', gain: 0.1, f1: 55 })
    this._noise(0.7, { type: 'lowpass', f0: 400, f1: 60, gain: 0.2 })
  }
  bossRoar() {
    this._tone(70, 0.9, { type: 'sawtooth', gain: 0.22, f1: 42 })
    this._noise(0.9, { type: 'lowpass', f0: 500, f1: 90, gain: 0.28 })
  }
  bossSlam() {
    this._noise(0.5, { type: 'lowpass', f0: 700, f1: 45, q: 0.7, gain: 0.45 })
    this._tone(62, 0.45, { type: 'sine', gain: 0.3, f1: 28 })
  }
  victory() {
    const seq = [523.25, 659.25, 783.99, 1046.5, 783.99, 1046.5, 1318.5]
    seq.forEach((f, i) => this._tone(f, 0.55, { type: 'triangle', gain: 0.08, delay: i * 0.13 }))
  }
}

import { clamp } from './utils.js'

const KEYMAP = {
  KeyW: 'up', ArrowUp: 'up',
  KeyS: 'down', ArrowDown: 'down',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  KeyJ: 'attack', KeyF: 'attack', Space: 'jump',
  KeyK: 'skill', KeyL: 'lock',
  ShiftLeft: 'dodge', ShiftRight: 'dodge',
  KeyE: 'interact', KeyQ: 'potion',
  Escape: 'pause', KeyP: 'pause',
  Enter: 'confirm'
}

export class Input {
  constructor(canvas) {
    this.canvas = canvas
    this.move = { x: 0, y: 0 }
    this.look = { x: 0, y: 0 }
    this.keys = new Set()
    this.queued = new Map()
    this.held = new Set()
    this.enabled = true
    this.stickPointer = null
    this.lookPointer = null
    this.lastLook = { x: 0, y: 0 }
    this._padActive = false
    this._bindKeyboard()
    this._bindStick()
    this._bindLook()
    this._bindActions()
  }

  _bindKeyboard() {
    window.addEventListener('keydown', e => {
      const action = KEYMAP[e.code]
      if (!action) return
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault()
      if (!this.keys.has(action)) this.press(action)
      this.keys.add(action)
      this.held.add(action)
    })
    window.addEventListener('keyup', e => {
      const action = KEYMAP[e.code]
      if (!action) return
      this.keys.delete(action)
      this.held.delete(action)
    })
    window.addEventListener('blur', () => { this.keys.clear(); this.held.clear(); this.move.x = this.move.y = 0 })
  }

  press(action) {
    this.queued.set(action, (this.queued.get(action) || 0) + 1)
  }

  consume(action) {
    const n = this.queued.get(action) || 0
    if (n > 0) { this.queued.set(action, 0); return true }
    return false
  }

  isHeld(action) { return this.held.has(action) || this.keys.has(action) }

  clearQueued() { this.queued.clear() }

  _bindStick() {
    const zone = document.getElementById('stick-zone')
    const base = document.getElementById('stick-base')
    const knob = document.getElementById('stick-knob')
    if (!zone || !base || !knob) return
    const radius = 40
    const update = (e) => {
      const rect = base.getBoundingClientRect()
      const cx = rect.left + rect.width / 2
      const cy = rect.top + rect.height / 2
      let dx = e.clientX - cx
      let dy = e.clientY - cy
      const len = Math.hypot(dx, dy)
      if (len > radius) { dx = dx / len * radius; dy = dy / len * radius }
      const nx = dx / radius, ny = dy / radius
      this.move.x = Math.abs(nx) > 0.08 ? nx : 0
      this.move.y = Math.abs(ny) > 0.08 ? ny : 0
      knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`
      zone.classList.add('active')
    }
    const reset = () => {
      this.stickPointer = null
      this.move.x = 0; this.move.y = 0
      knob.style.transform = 'translate(-50%,-50%)'
      zone.classList.remove('active')
    }
    zone.addEventListener('pointerdown', e => {
      e.preventDefault()
      this.stickPointer = e.pointerId
      try { zone.setPointerCapture(e.pointerId) } catch {}
      update(e)
    })
    zone.addEventListener('pointermove', e => {
      if (this.stickPointer !== e.pointerId) return
      e.preventDefault(); update(e)
    })
    zone.addEventListener('pointerup', e => { if (this.stickPointer === e.pointerId) reset() })
    zone.addEventListener('pointercancel', e => { if (this.stickPointer === e.pointerId) reset() })
    zone.addEventListener('lostpointercapture', () => { if (this.stickPointer !== null) reset() })
  }

  _bindLook() {
    const area = this.canvas
    if (!area) return
    const el = area.parentElement || area
    const onDown = e => {
      if (e.pointerType === 'mouse' && e.button !== 0) return
      if (this.lookPointer !== null) return
      this.lookPointer = e.pointerId
      this.lastLook.x = e.clientX; this.lastLook.y = e.clientY
      try { el.setPointerCapture(e.pointerId) } catch {}
    }
    const onMove = e => {
      if (this.lookPointer !== e.pointerId) return
      const dx = e.clientX - this.lastLook.x
      const dy = e.clientY - this.lastLook.y
      this.lastLook.x = e.clientX; this.lastLook.y = e.clientY
      const limit = e.pointerType === 'mouse' ? 0.0034 : 0.0046
      this.look.x += dx * limit
      this.look.y += dy * limit
      // wheel-like visual feedback not needed
    }
    const onUp = e => { if (this.lookPointer === e.pointerId) this.lookPointer = null }
    el.addEventListener('pointerdown', onDown)
    el.addEventListener('pointermove', onMove)
    el.addEventListener('pointerup', onUp)
    el.addEventListener('pointercancel', onUp)
    el.addEventListener('lostpointercapture', onUp)
    el.addEventListener('contextmenu', e => e.preventDefault())
  }

  _bindActions() {
    for (const btn of document.querySelectorAll('[data-action]')) {
      const action = btn.dataset.action
      const down = e => {
        e.preventDefault(); e.stopPropagation()
        this.press(action)
        this.held.add(action)
        btn.classList.add('pressed')
      }
      const up = e => {
        e.stopPropagation()
        this.held.delete(action)
        btn.classList.remove('pressed')
      }
      btn.addEventListener('pointerdown', down)
      btn.addEventListener('pointerup', up)
      btn.addEventListener('pointercancel', up)
      btn.addEventListener('pointerleave', up)
    }
  }

  consumeLook() {
    const l = { ...this.look }
    this.look.x = 0; this.look.y = 0
    return l
  }

  update() {
    if (this.keys.has('up') || this.keys.has('down') || this.keys.has('left') || this.keys.has('right')) {
      if (this.stickPointer === null) {
        this.move.x = (this.keys.has('right') ? 1 : 0) - (this.keys.has('left') ? 1 : 0)
        this.move.y = (this.keys.has('down') ? 1 : 0) - (this.keys.has('up') ? 1 : 0)
      }
    }
    this.move.x = clamp(this.move.x, -1, 1)
    this.move.y = clamp(this.move.y, -1, 1)
  }
}
